INSERT IGNORE INTO textbot(id_text,text) VALUES
('report_reseller_purchase','📣 خرید موفق در ربات نماینده ثبت شد.\n\n{first_purchase}\n👤 کاربر: <code>{user_id}</code> — @{user_username}\n🧑‍💼 نماینده: <code>{agent_id}</code> — ربات @{reseller_bot}\n🔐 نام کانفیگ: <code>{config_username}</code>\n🖥 پنل: {panel_name}\n⏳ مدت: {service_days} روز | 💾 حجم: {volume_gb} GB\n💰 موجودی کاربر: {user_balance_before} ← {user_balance_after} تومان\n💼 موجودی نماینده: {agent_balance_before} ← {agent_balance_after} تومان\n💳 قیمت محصول: {product_price} تومان\n🧾 پیگیری: <code>{tracking_code}</code>\n🕒 زمان: {purchase_time}'),
('report_reseller_extend','♻️ تمدید سرویس در ربات نماینده ثبت شد.\n\n👤 کاربر: <code>{user_id}</code> — @{user_username}\n🧑‍💼 نماینده: <code>{agent_id}</code> — ربات @{reseller_bot}\n🔐 سرویس: <code>{config_username}</code>\n🛍 محصول: {product_name}\n🖥 پنل: {panel_name}\n⏳ مدت: {service_days} روز | 💾 حجم: {volume_gb} GB\n💰 موجودی کاربر: {user_balance_before} ← {user_balance_after} تومان\n💼 موجودی نماینده: {agent_balance_before} ← {agent_balance_after} تومان\n💳 مبلغ تمدید: {product_price} تومان\n🕒 زمان: {purchase_time}'),
('report_reseller_test','🧪 اکانت تست در ربات نماینده ساخته شد.\n\n👤 کاربر: <code>{user_id}</code> — @{user_username}\n🧑‍💼 نماینده: <code>{agent_id}</code> — ربات @{reseller_bot}\n🔐 کانفیگ: <code>{config_username}</code>\n🖥 پنل: {panel_name}\n⏳ زمان تست: {test_hours} ساعت | 💾 حجم: {test_volume} MB\n🧾 پیگیری: <code>{tracking_code}</code>\n🕒 زمان: {purchase_time}'),
('alert_reseller_no_credit_customer','❌ اعتبار فروشنده برای ساخت این سرویس کافی نیست.\nلطفاً با فروشنده تماس بگیرید تا حساب نمایندگی را شارژ کند.'),
('alert_reseller_no_credit_admin','⚠️ اعتبار نماینده برای فروش کافی نیست.\nنماینده: <code>{agent_id}</code>\nموجودی فعلی: {agent_balance} تومان\nمبلغ لازم: {required_amount} تومان\nلطفاً حساب نمایندگی شارژ شود.'),
('alert_reseller_low_balance','⚠️ هشدار کاهش اعتبار نمایندگی\nنماینده: <code>{agent_id}</code>\nموجودی فعلی: {agent_balance} تومان\nحد هشدار: {threshold} تومان\nبرای جلوگیری از توقف فروش، حساب را شارژ کنید.');
